import sys

def main():
    data = sys.stdin.read().split('\n')
    ptr = 0
    Q = int(data[ptr].strip())
    ptr += 1
    queries = []
    for _ in range(Q):
        q_line = data[ptr].strip()
        if not q_line:
            ptr += 1
            continue
        q_parts = q_line.split()
        if q_parts[0] == '2':
            queries.append((2, int(q_parts[1])))
        else:
            queries.append(('1', int(q_parts[1])))

    answers = []
    stack = []
    for cmd, arg in queries:
        if cmd == 1:
            stack.append(arg)
        else:
            res = stack.pop()
            answers.append(str(res))

    print('\n'.join(answers))

if __name__ == "__main__":
    main()

