def main():
    import sys
    input = sys.stdin.readline
    from collections import deque

    n = int(input())
    arr = list(map(int, input().split()))
    if n == 0:
        print(0)
        return

    # BFS
    has_zero = any(x == 0 for x in arr)
    if not has_zero:
        print(0)
        return

    zero_positions = [i for i, num in enumerate(arr) if num == 0]
    visited = [[False]*len(arr) for _ in range(4)]
    adj = {0: [], 1: [], 2: [], 3: []}
    for i in range(n):
        if arr[i] == 0:
            adj[0].append(i)
            adj[1].append(i)
            adj[2].append(i)
            adj[3].append(i)
    for i in range(n):
        if arr[i] == 0 and not visited[0][i]:
            visited[0][i] = True
            q = deque([i])
            dirs = [(-1, 1), (1, -1), (1, 1), (-1, -1)]
            while q:
                idx = q.popleft()
                d = 0 if arr[idx] >= 0 else 1
                for di, dir in enumerate(dirs):
                    ni, di = idx+dir[0], d+dir[1]
                    if 0 <= ni < n and not visited[d][ni] and arr[ni] == 0:
                        visited[d][ni] = True
                        q.append(ni)
    for mask in range(4):
        for i in range(n):
            if arr[i] == 0 and not visited[mask][i]:
                print("0")
                return
    print(4**len(zero_positions))

if __name__ == "__main__":
    main()
