```python
def main():
    import sys
    import itertools

    data = sys.stdin.read().splitlines()
    N, K = map(int, data[0].split())
    S = data[1].strip()
    S_list = list(S)
    n = len(S_list)
    used = set()
    available = set(range(1, K + 1))
    blocks = []

    for i in range(K):
        if S_list[i] == 'O':
            used.add(i)
            blocks.append(i)

    # For K consecutive 'O's at the start
    if 0 <= blocks[0] - K < len(blocks):
        used.update(set(range(blocks[0] - K, blocks[0] + 1)))
        blocks = blocks[1:]

    # Remove blocks that are inside or at the ends
    new_blocks = []
    for b in blocks:
        while b - K >= len(blocks):
            b += 1
        new_blocks.append(b)
    blocks_now = new_blocks
    while set(blocks).issubset(set(range(len(blocks_now)))):
        blocks = new_blocks
    remaining_blocks = []
    for b in blocks:
        if b - K >= len(blocks):
            b += 1
        remaining_blocks.append(b)
        if b % (K-1) == 0:
            remaining_blocks.append(b)

    # Main loop
    res = 0
    while True:
        if not remaining_blocks:
            break
        smallest = min(remaining_blocks)
        res += smallest
        cnt = 1
        current = smallest + (K - 1) * cnt
        while cnt < (K - 1):
            for b in remaining_blocks:
                if b == current + 1:
                    cnt += 1
                    break
                if cnt == (K - 1):
                    current = b
                elif b > current:
                    break
                else:
                    if b == current + 1:
                        cnt += 1
                        break
            if cnt == (K - 1):
                break
        remaining_blocks = [b for b in remaining_blocks if b < current + 1]
        if not remaining_blocks:
            break
        remaining_blocks = list(filter(lambda x: x > current, remaining_blocks))
        if not remaining_blocks:
            break
        smallest = min(remaining_blocks)
    print(res)

